export function validateTeamRoster(teamCodeOrRoster: string | any[], roster?: any[]): boolean {
  const list = Array.isArray(teamCodeOrRoster) ? teamCodeOrRoster : roster || [];
  if (!Array.isArray(list)) return false;
  const hasQB = list.some((r) => r.position === 'QB');
  const hasRB = list.some((r) => r.position === 'RB');
  const hasWR = list.some((r) => r.position === 'WR');
  const hasTE = list.some((r) => r.position === 'TE');
  return hasQB && hasRB && hasWR && hasTE && list.length >= 6;
}
